  const book = await loadBook(target);
  return Object.keys(book.entries)
    .filter((k) => book.entries[k])
    .sort((a, b) => Number(a) - Number(b))
    .map((k) => ({ key: String(k), raw: String(book.entries[k].comment || "") }));
